#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<vector<int>> graph(N);
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    vector<int> parent(N, -1), order;
    order.reserve(N);
    order.push_back(0);

    for (int i = 0; i < (int)order.size(); ++i) {
        int v = order[i];
        for (int u : graph[v]) {
            if (u == parent[v]) continue;
            parent[u] = v;
            order.push_back(u);
        }
    }

    vector<int> nearest(N), farthest(N);
    const int INF = 1e9;

    auto feasible = [&](int R) {
        int centers = 0;

        for (int i = N - 1; i >= 0; --i) {
            int v = order[i];
            int d = INF;
            int h = 0;

            for (int u : graph[v]) {
                if (parent[u] != v) continue;
                if (nearest[u] != INF) d = min(d, nearest[u] + 1);
                if (farthest[u] >= 0) h = max(h, farthest[u] + 1);
            }

            if (d != INF && h + d <= R) h = -1;

            if (h == R) {
                ++centers;
                if (centers > K) return false;
                d = 0;
                h = -1;
            }

            nearest[v] = d;
            farthest[v] = h;
        }

        if (farthest[0] >= 0) ++centers;
        return centers <= K;
    };

    int lo = 0, hi = N;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (feasible(mid)) hi = mid;
        else lo = mid + 1;
    }

    cout << lo << '\n';
    return 0;
}
